#ifndef PULSE_NATIVE_UI_MODEL_H
#define PULSE_NATIVE_UI_MODEL_H
#include "ui.h"
#ifdef __cplusplus
extern "C" {
#endif
#pragma pack(push, 8)
#define PULSE_UI_MODEL_INTERFACE "pulse.ui.model"
#define PULSE_UI_MODEL_VERSION 1u
/* General-purpose controls backed by the existing renderer. All borrowed arrays/strings are
   copied synchronously. Optional fields use present=0/1; absent preserves host defaults.
   UTF-8 byte budget 65536; nodes 128/depth8; menus128/depth4; total data rows4096/depth8.
   This C ABI uses the same property semantics as the existing UiTree contract.
   Structure submission uses a temporary in-memory DOM for shared validation, never
   JSON text serialization/parsing. High-frequency set_states remains typed directly. */
typedef struct PulseUiModelString { uint32_t present; PulseStringView value; } PulseUiModelString;
typedef struct PulseUiModelBool { uint32_t present; uint32_t value; } PulseUiModelBool;
typedef struct PulseUiModelInt { uint32_t present; int64_t value; } PulseUiModelInt;
typedef struct PulseUiModelStrings { uint32_t present; const PulseStringView* data; uint32_t count; } PulseUiModelStrings;
enum {
    PULSE_UI_MODEL_STACK = 0,
    PULSE_UI_MODEL_GRID = 1,
    PULSE_UI_MODEL_GROUP = 2,
    PULSE_UI_MODEL_SCROLL_VIEW = 3,
    PULSE_UI_MODEL_TEXT = 4,
    PULSE_UI_MODEL_BUTTON = 5,
    PULSE_UI_MODEL_TEXT_INPUT = 6,
    PULSE_UI_MODEL_CHECKBOX = 7,
    PULSE_UI_MODEL_SELECT = 8,
    PULSE_UI_MODEL_PROGRESS = 9,
    PULSE_UI_MODEL_DIVIDER = 10,
    PULSE_UI_MODEL_TABS = 11,
    PULSE_UI_MODEL_TAB = 12,
    PULSE_UI_MODEL_SWITCH = 14,
    PULSE_UI_MODEL_RADIO = 15,
    PULSE_UI_MODEL_SLIDER = 16,
    PULSE_UI_MODEL_SEGMENTED = 17,
    PULSE_UI_MODEL_BADGE = 18,
    PULSE_UI_MODEL_TAG = 19,
    PULSE_UI_MODEL_INFO_BAR = 20,
    PULSE_UI_MODEL_SPLIT_BUTTON = 21,
    PULSE_UI_MODEL_MENU_BUTTON = 22,
    PULSE_UI_MODEL_EMPTY_STATE = 25,
    PULSE_UI_MODEL_VIRTUAL_LIST = 26,
    PULSE_UI_MODEL_TREE = 27,
    PULSE_UI_MODEL_DATA_TABLE = 28,
    PULSE_UI_MODEL_SPLIT_PANE = 31,
    /* Reserved holes are invalid types; COUNT is the numeric range upper bound. */
    PULSE_UI_MODEL_COUNT = 41
};
typedef struct PulseUiModelMenuItem PulseUiModelMenuItem;
typedef struct PulseUiModelMenus { uint32_t present; const PulseUiModelMenuItem* data; uint32_t count; } PulseUiModelMenus;
struct PulseUiModelMenuItem {
    uint32_t size;
    PulseUiModelString id, text, command, glyph, shortcut;
    PulseUiModelBool enabled, checked, separator;
    PulseUiModelMenus children;
};
typedef struct PulseUiModelRow PulseUiModelRow;
typedef struct PulseUiModelRows { uint32_t present; const PulseUiModelRow* data; uint32_t count; } PulseUiModelRows;
struct PulseUiModelRow {
    uint32_t size;
    PulseStringView id;
    PulseUiModelString text, glyph, command;
    PulseUiModelStrings cells;
    PulseUiModelRows children;
    PulseUiModelBool expanded, enabled;
};
typedef struct PulseUiModelColumn { uint32_t size; PulseStringView id, text; PulseUiModelInt width; } PulseUiModelColumn;
typedef struct PulseUiModelColumns { uint32_t present; const PulseUiModelColumn* data; uint32_t count; } PulseUiModelColumns;
typedef struct PulseUiModelValidation {
    uint32_t size;
    PulseUiModelBool required;
    PulseUiModelInt min_length, max_length;
    PulseStringView message;
} PulseUiModelValidation;
/* Reserved actual UiTree provider shape. Non-null data_source is UNAVAILABLE until
   owner-scoped provider/resolver integration is implemented; no fake static fallback. */
typedef struct PulseUiModelDataSource {
    uint32_t size;
    PulseStringView source;
    PulseUiModelInt page_size;
    PulseUiModelString filter_state, sort_state, status_state, error_state, progress_state;
} PulseUiModelDataSource;
typedef struct PulseUiModelNode PulseUiModelNode;
typedef struct PulseUiModelNodes { uint32_t present; const PulseUiModelNode* data; uint32_t count; } PulseUiModelNodes;
struct PulseUiModelNode {
    uint32_t size, type;
    PulseStringView id;
    PulseUiModelString text;
    PulseUiModelString command;
    PulseUiModelString binding;
    PulseUiModelString state;
    PulseUiModelString orientation;
    PulseUiModelString placeholder;
    PulseUiModelString glyph;
    PulseUiModelString keycap;
    PulseUiModelString detail;
    PulseUiModelString message;
    PulseUiModelString color;
    PulseUiModelString close_command;
    PulseUiModelString enabled_binding;
    PulseUiModelString visible_binding;
    PulseUiModelString role;
    PulseUiModelString alignment;
    PulseUiModelString badge_text;
    PulseUiModelString status;
    PulseUiModelString trailing_glyph;
    PulseUiModelString summary;
    PulseUiModelString filter_text;
    PulseUiModelString filter_command;
    PulseUiModelString sort_command;
    PulseUiModelString modified;
    PulseUiModelString file_type;
    PulseUiModelString file_size;
    PulseUiModelString helper;
    PulseUiModelString count_label;
    PulseUiModelString action_text;
    PulseUiModelString center_text;
    PulseUiModelString right_text;
    PulseUiModelString kind;
    PulseUiModelBool checked;
    PulseUiModelBool enabled;
    PulseUiModelBool visible;
    PulseUiModelBool icon_only;
    PulseUiModelBool bordered;
    PulseUiModelBool selected;
    PulseUiModelBool current;
    PulseUiModelBool separator;
    PulseUiModelBool dot;
    PulseUiModelBool move_intent;
    PulseUiModelBool expanded;
    PulseUiModelBool cut;
    PulseUiModelBool missing;
    PulseUiModelBool ready;
    PulseUiModelInt value;
    PulseUiModelInt columns;
    PulseUiModelInt gap;
    PulseUiModelInt min_height;
    PulseUiModelInt min_width;
    PulseUiModelInt max_width;
    PulseUiModelInt max_height;
    PulseUiModelInt flex;
    PulseUiModelInt stops;
    PulseUiModelInt item_count;
    PulseUiModelInt capacity;
    PulseUiModelInt free_bytes;
    PulseUiModelInt total_bytes;
    PulseUiModelNodes children;
    PulseUiModelStrings options, tag_colors;
    PulseUiModelMenus menu, actions;
    PulseUiModelRows rows;
    PulseUiModelColumns data_columns; /* DataTable columns; integer columns belongs to Grid. */
    const PulseUiModelValidation* validation;
    const PulseUiModelDataSource* data_source;
};
typedef struct PulseUiModelDataOperation { uint32_t size; PulseStringView target, operation; } PulseUiModelDataOperation;
typedef struct PulseUiModelAction {
    uint32_t size;
    PulseStringView id;
    const PulseUiState* updates;
    uint32_t update_count;
    PulseUiModelStrings validate;
    const PulseUiModelDataOperation* data_operation; /* Non-null returns UNAVAILABLE. */
} PulseUiModelAction;
typedef struct PulseUiModelTree {
    uint32_t size;
    const PulseUiModelNode* root;
    const PulseUiState* states;
    uint32_t state_count;
    const PulseUiModelAction* actions;
    uint32_t action_count;
    const PulseStringView* commands; /* Declared native callback IDs, <=128; separate from local actions. */
    uint32_t command_count;
} PulseUiModelTree;
typedef struct PulseUiModelV1 {
    uint32_t size, version;
    void* context;
    PulseStatus (PULSE_CALL *create)(void*, PulseStringView title, const PulseUiModelTree*, uint64_t* panel);
    PulseStatus (PULSE_CALL *update)(void*, uint64_t panel, const PulseUiModelTree*);
    PulseStatus (PULSE_CALL *subscribe_command)(void*, uint64_t panel, PulseStringView command,
        PulseUiClickFn callback, void* user, uint64_t* subscription);
    PulseStatus (PULSE_CALL *set_states)(void*, uint64_t panel, const PulseUiState*, uint32_t count);
    /* needed excludes terminator. Null buffer/capacity 0 queries size. No partial copy. */
    PulseStatus (PULSE_CALL *get_state)(void*, uint64_t panel, PulseStringView key, char* buffer,
        uint32_t capacity, uint32_t* needed);
    PulseStatus (PULSE_CALL *unsubscribe)(void*, uint64_t subscription);
    PulseStatus (PULSE_CALL *close)(void*, uint64_t panel);
    /* Callback user pointers belong to the plugin; unsubscribe/close invalidate them synchronously.
       Panel/subscription IDs are never reused. No exception may cross this ABI.
       Updates validate atomically, retain existing state keys and registrations by command ID.
       callback's string argument is command ID (including menu/close/filter/sort/row),
       not node ID. Local actions mutate state and never invoke native callbacks.
       context.* bindings are UNAVAILABLE until an owner resolver is connected. */
} PulseUiModelV1;
#pragma pack(pop)
#ifdef __cplusplus
}
#endif
#endif

#ifndef PULSE_NATIVE_UI_DATA_H
#define PULSE_NATIVE_UI_DATA_H
#include "ui_model.h"
#ifdef __cplusplus
extern "C" {
#endif
#pragma pack(push, 8)
#define PULSE_UI_DATA_INTERFACE "pulse.ui.data"
#define PULSE_UI_DATA_VERSION 1u
enum { PULSE_UI_DATA_REFRESH = 0, PULSE_UI_DATA_NEXT_PAGE = 1, PULSE_UI_DATA_CANCEL = 2 };
enum { PULSE_UI_DATA_LOADING = 0, PULSE_UI_DATA_READY = 1, PULSE_UI_DATA_ERROR = 2 };
enum { PULSE_UI_DATA_SNAPSHOT = 0, PULSE_UI_DATA_DELTA = 1 };
typedef struct PulseUiDataRequest {
    uint32_t size, page_size;
    uint64_t request, provider, panel;
    PulseStringView node, filter, sort, cursor;
} PulseUiDataRequest;
typedef void (PULSE_CALL *PulseUiDataRequestFn)(void* user, const PulseUiDataRequest* request);
typedef void (PULSE_CALL *PulseUiDataCancelFn)(void* user, uint64_t request);
typedef struct PulseUiDataBinding {
    uint32_t size, page_size; /* 1..256; <=16 bindings and <=16 providers per instance. */
    PulseStringView filter_state, sort_state, status_state, error_state, progress_state;
} PulseUiDataBinding;
typedef struct PulseUiDataPage {
    uint32_t size, status, mode, progress; /* progress 0..100; see enums above. */
    PulseStringView revision, base_revision, next_cursor, error;
    const PulseUiModelRow* rows;
    uint32_t row_count;
    const PulseStringView* removed_ids;
    uint32_t removed_count;
} PulseUiDataPage;
/* Request/cancel callbacks and all operations except publish run on the UI thread.
   Callbacks must return promptly; compute on plugin-owned workers. Data control
   operations cannot reenter a request/cancel callback; use dispatch to defer them.
   publish and pulse.ui.close remain available during callbacks. No exceptions
   cross the ABI. Request views last only through the callback. publish copies all
   borrowed data synchronously, may run on any thread, and never invokes plugin code.
   Cancel invalidates the request BEFORE the cancel callback. Later publish returns
   STATE. cancel callback only signals work; destroy joins all plugin-owned workers.
   Host context remains valid through plugin destroy, not after it.

   bind targets an existing empty virtualList/tree/dataTable in pulse.ui.model.
   It attaches the shared renderer's real data controller, not a second widget.
   Selection state must initially be empty. Config state keys must exist, have
   distinct roles, and not overlap the selection key. sort starts nameAsc/nameDesc.
   bind does not request data; request REFRESH starts a live stream. Filter/sort
   state changes automatically cancel/restart it. NEXT_PAGE cancels the previous
   stream and requests its cursor; the revision must match. Rebind after model
   update: successful update, close, stop, unregister and unbind cancel requests.
   Unbind clears displayed rows and selection. Providers remain until unregister
   or stop. Handles belong to one plugin instance and cannot be reused elsewhere.

   SNAPSHOT publishes <=page_size rows (<=4096 recursive rows), depth<=8, <=16
   cells/row, total UTF-8<=65536 bytes/page; IDs unique within a page, <=64 bytes.
   Rows have the same semantics as PulseUiModelRow; row commands must be declared
   native commands. READY requires a nonempty revision (<=128 bytes). Cursors<=256
   bytes, errors<=1024. LOADING/ERROR carry no rows/cursor/delta; ERROR needs error.
   DELTA is READY with base_revision matching displayed revision; it upserts stable
   row IDs and removes top-level IDs (<=256). It requires an established snapshot,
   is not allowed for a next-page stream, and clears pagination. Tree changes to
   descendants replace their top-level ancestor. Total displayed rows<=4096.
   Initial empty/error/loading, refresh, pagination and deltas are observable via
   configured state keys. Stale revisions/overflow become error states, not success.
   The controller inbox is bounded (64 pages); overflow fails the stream until
   refresh. PULSE_OK on publish means copied/queued, not yet displayed. */
typedef struct PulseUiDataV1 {
    uint32_t size, version;
    void* context;
    PulseStatus (PULSE_CALL *register_provider)(void*, PulseUiDataRequestFn, PulseUiDataCancelFn, void* user, uint64_t* provider);
    PulseStatus (PULSE_CALL *unregister_provider)(void*, uint64_t provider);
    PulseStatus (PULSE_CALL *bind)(void*, uint64_t panel, PulseStringView node, uint64_t provider, const PulseUiDataBinding*);
    PulseStatus (PULSE_CALL *unbind)(void*, uint64_t panel, PulseStringView node);
    PulseStatus (PULSE_CALL *request)(void*, uint64_t panel, PulseStringView node, uint32_t operation);
    PulseStatus (PULSE_CALL *publish)(void*, uint64_t request, const PulseUiDataPage*);
} PulseUiDataV1;
#pragma pack(pop)
#ifdef __cplusplus
}
#endif
#endif

#ifndef PULSE_NATIVE_DIRECTORIES_H
#define PULSE_NATIVE_DIRECTORIES_H
#include "abi.h"
#ifdef __cplusplus
extern "C" {
#endif
#define PULSE_DIRECTORIES_INTERFACE_NAME "pulse.directories"
#define PULSE_DIRECTORIES_VERSION_1 1u
/* Additive native directory service. All calls and callbacks use the owner UI
   thread. Filesystem enumeration and watch I/O run on host workers. PULSE_OK
   accepts work; callbacks are deferred, and borrowed fields expire on return.
   Requires files.readDirectory; watch also requires files.watchDirectory;
   open_entry additionally requires files.open. A trusted DLL is not a sandbox.
   open accepts absolute drive/UNC paths, not device/virtual/relative paths.
   At most 4 directories, 32 pending requests and 8 watches per attachment.
   Snapshots contain at most 65536 rows / 16 MiB UTF-8 names, never truncated.
   Snapshot IDs and entry IDs are owner/directory/snapshot bound, not file IDs.
   Successful refresh replaces the snapshot; failed refresh preserves it.
   list pages use explicit offset (limit 1..256) against an immutable snapshot.
   Watch notifications are coalesced invalidations, not an exact change journal.
   After READY, refresh and repeat on INVALIDATED/overflow to avoid an arm gap.
   close/cancel/unwatch suppress future callbacks immediately; an on-stack
   callback may finish. Stop never waits for filesystem I/O on the UI thread.
   No exception may cross this ABI. Context expires after plugin destroy. */
#pragma pack(push, 8)
typedef uint64_t PulseDirectoryId;
typedef uint64_t PulseDirectoryRequestId;
typedef uint64_t PulseDirectoryWatchId;
enum { PULSE_DIRECTORY_OPEN = 1u, PULSE_DIRECTORY_REFRESH = 2u,
       PULSE_DIRECTORY_LIST = 3u, PULSE_DIRECTORY_OPEN_ENTRY = 4u };
enum { PULSE_DIRECTORY_WATCH_READY = 1u, PULSE_DIRECTORY_INVALIDATED = 2u,
       PULSE_DIRECTORY_WATCH_ERROR = 3u };
enum { PULSE_DIRECTORY_ENTRY_FOLDER = 1u, PULSE_DIRECTORY_ENTRY_REPARSE = 2u };
typedef struct PulseDirectoryRow {
    uint64_t entry_id;
    PulseStringView name;
    uint64_t size_bytes;
    uint64_t modified_filetime;
    uint32_t attributes;
    uint32_t flags;
} PulseDirectoryRow;
typedef struct PulseDirectoryReply {
    uint32_t size;
    uint32_t operation;
    PulseDirectoryRequestId request_id;
    PulseStatus status;
    uint32_t system_error;
    PulseStringView error;
    PulseDirectoryId directory_id;
    uint64_t snapshot_id;
    PulseStringView path;
    uint64_t total;
    const PulseDirectoryRow *rows;
    uint32_t count;
    uint32_t next_offset; /* UINT32_MAX when the immutable snapshot is exhausted. */
} PulseDirectoryReply;
typedef struct PulseDirectoryChange {
    uint32_t size;
    uint32_t kind;
    PulseDirectoryWatchId watch_id;
    PulseDirectoryId directory_id;
    uint64_t sequence;
    PulseStatus status;
    uint32_t overflow;
    PulseStringView error;
} PulseDirectoryChange;
typedef void(PULSE_CALL *PulseDirectoryCompletionFn)(void *, const PulseDirectoryReply *);
typedef void(PULSE_CALL *PulseDirectoryChangeFn)(void *, const PulseDirectoryChange *);
typedef struct PulseDirectoriesV1 {
    uint32_t size;
    uint32_t version;
    void *context;
    PulseStatus(PULSE_CALL *open)(void *, PulseStringView path, PulseDirectoryCompletionFn, void *, PulseDirectoryRequestId *);
    PulseStatus(PULSE_CALL *refresh)(void *, PulseDirectoryId, PulseDirectoryCompletionFn, void *, PulseDirectoryRequestId *);
    PulseStatus(PULSE_CALL *list)(void *, PulseDirectoryId, uint64_t snapshot_id, uint32_t offset, uint32_t limit,
        PulseDirectoryCompletionFn, void *, PulseDirectoryRequestId *);
    /* Resolves an existing snapshot entry, then delegates to Pulse's normal
       navigation/open routing. Success means dispatch accepted, not app launch
       or document execution completed. Stale snapshot/entry is rejected. */
    PulseStatus(PULSE_CALL *open_entry)(void *, PulseDirectoryId, uint64_t snapshot_id, uint64_t entry_id,
        PulseDirectoryCompletionFn, void *, PulseDirectoryRequestId *);
    PulseStatus(PULSE_CALL *watch)(void *, PulseDirectoryId, PulseDirectoryChangeFn, void *, PulseDirectoryWatchId *);
    PulseStatus(PULSE_CALL *unwatch)(void *, PulseDirectoryWatchId);
    PulseStatus(PULSE_CALL *close)(void *, PulseDirectoryId);
    PulseStatus(PULSE_CALL *cancel)(void *, PulseDirectoryRequestId);
} PulseDirectoriesV1;
#pragma pack(pop)
#ifdef __cplusplus
}
#endif
#endif

#ifndef PULSE_NATIVE_CONTEXT_H
#define PULSE_NATIVE_CONTEXT_H
#include "abi.h"
#ifdef __cplusplus
extern "C" {
#endif
#define PULSE_CONTEXT_INTERFACE_NAME "pulse.context"
#define PULSE_CONTEXT_VERSION_1 1u
/* UI thread only. Declarations do not gate calls.
   Observation uses the owner's already loaded state; get/subscribe never enumerate files or
   selections. Changes are coalesced at the host's 30 ms session tick, not a
   lossless event journal. Loading clears selection summary. Revision fields
   are monotonic per attachment; a multi-selection change is observable even
   when its count/name summary is unchanged. Initial delivery is deferred.
   Strings are borrowed through the callback; copy before returning.
   Unsubscribe/stop suppress future callbacks; on-stack callbacks may finish.
   16 subscriptions per attachment. Context lives through plugin destroy.
   No C++ exception may cross an ABI callback. */
#pragma pack(push, 8)
typedef uint64_t PulseContextSubscriptionId;
enum { PULSE_CONTEXT_INITIAL = 1u, PULSE_CONTEXT_NAVIGATION = 2u,
       PULSE_CONTEXT_SELECTION = 4u, PULSE_CONTEXT_VIEW = 8u };
typedef struct PulseContextSnapshot {
    uint32_t size;
    uint32_t changes;
    uint64_t revision;
    uint64_t navigation_revision;
    uint64_t selection_revision;
    PulseStringView directory;
    PulseStringView selection_name;
    PulseStringView view_mode;
    uint64_t selection_count;
    uint32_t loading;
    uint32_t reserved;
} PulseContextSnapshot;
typedef void(PULSE_CALL *PulseContextChangeFn)(void *, const PulseContextSnapshot *);
enum { PULSE_CONTEXT_ENTRY_DIRECTORY = 1u };
typedef struct PulseContextSelectionEntry {
    uint32_t size;
    uint32_t flags;
    PulseStringView path;
    PulseStringView name;
} PulseContextSelectionEntry;
typedef struct PulseContextSelectionSnapshot {
    uint32_t size;
    uint64_t selection_revision;
    PulseStringView directory;
    const PulseContextSelectionEntry *entries;
    uint32_t entry_count;
} PulseContextSelectionSnapshot;
typedef void(PULSE_CALL *PulseContextSelectionFn)(void *, const PulseContextSelectionSnapshot *);

typedef struct PulseContextV1 {
    uint32_t size;
    uint32_t version;
    void *context;
    /* get calls back synchronously with the latest loaded context. It never
       retains the callback or user pointer; use subscribe for deferred events. */
    PulseStatus(PULSE_CALL *get)(void *, PulseContextChangeFn, void *);
    PulseStatus(PULSE_CALL *subscribe)(void *, PulseContextChangeFn, void *, PulseContextSubscriptionId *);
    PulseStatus(PULSE_CALL *unsubscribe)(void *, PulseContextSubscriptionId);
    /* Synchronous loaded selection, no disk access. Borrowed only during callback.
       Ordinary directories support an empty selection. Loading returns STATE;
       virtual/content views or >4096 entries / >4 MiB UTF-8 return UNAVAILABLE.
       No partial delivery or recursive callback reads. */
    PulseStatus(PULSE_CALL *get_selection)(void *, PulseContextSelectionFn, void *);
} PulseContextV1;
#pragma pack(pop)
#ifdef __cplusplus
}
#endif
#endif

#ifndef PULSE_NATIVE_FILEOPS_H
#define PULSE_NATIVE_FILEOPS_H
#include "abi.h"
#include "directories.h"
#ifdef __cplusplus
extern "C" {
#endif
#define PULSE_FILEOPS_INTERFACE_NAME "pulse.fileops"
#define PULSE_FILEOPS_VERSION_1 1u
#define PULSE_FILEOPS_VERSION_2 2u
#define PULSE_FILEOPS_VERSION_3 3u
#define PULSE_FILEOPS_VERSION_4 4u
/* V1 controlled transfer actions use the current UI selection and the other
   visible pane as destination. Recycle-delete uses the current file selection
   and rejects sources that cannot be recycled. No plugin paths are accepted. Submit
   starts asynchronous host preparation and always presents Pulse's native
   confirmation before mutation. Query/cancel address only this attachment's
   requests. All calls are owner-UI-thread only; no exception crosses the ABI.
   Stop cancels this attachment's pending/running requests without waiting. */
#pragma pack(push, 8)
typedef uint64_t PulseFileOperationRequestId;
enum {
    PULSE_FILEOPS_COPY_SELECTION_TO_OTHER_PANE = 1u,
    PULSE_FILEOPS_MOVE_SELECTION_TO_OTHER_PANE = 2u,
    PULSE_FILEOPS_DELETE_SELECTION_TO_RECYCLE_BIN = 3u,
    PULSE_FILEOPS_COPY_SELECTION_TO_DIRECTORY = 4u,
    PULSE_FILEOPS_MOVE_SELECTION_TO_DIRECTORY = 5u,
    PULSE_FILEOPS_COPY_ENTRIES_TO_DIRECTORY = 6u,
    PULSE_FILEOPS_MOVE_ENTRIES_TO_DIRECTORY = 7u,
    PULSE_FILEOPS_COPY_DIRECTORY_TREE_TO_DIRECTORY = 8u
};
enum {
    PULSE_FILEOPS_PREPARING = 1u,
    PULSE_FILEOPS_WAITING_CONFIRMATION = 2u,
    PULSE_FILEOPS_QUEUED = 3u,
    PULSE_FILEOPS_RUNNING = 4u,
    PULSE_FILEOPS_CANCELLING = 5u,
    PULSE_FILEOPS_COMPLETED = 6u,
    PULSE_FILEOPS_PARTIAL = 7u,
    PULSE_FILEOPS_CANCELLED = 8u,
    PULSE_FILEOPS_FAILED = 9u
};
typedef struct PulseFileOperation {
    uint32_t size;
    uint32_t state;
    PulseFileOperationRequestId request_id;
    uint64_t task_id; /* Zero until Pulse has accepted the confirmed task. */
    uint64_t transferred_bytes;
    uint64_t total_bytes;
    uint64_t completed_items;
    uint64_t total_items;
    uint32_t percent; /* 0..100; zero while no determinate progress exists. */
    uint32_t cancel_requested;
    uint32_t terminal;
    uint32_t succeeded;
    uint32_t system_error;
    uint32_t reserved;
} PulseFileOperation;
typedef struct PulseFileOpsV1 {
    uint32_t size;
    uint32_t version;
    void *context;
    /* Copy/move require files.transferCurrentSelection and operations.own;
       delete requires files.deleteCurrentSelection and operations.own. All
       operations use the current selection and Pulse's native confirmation. */
    PulseStatus(PULSE_CALL *submit)(void *, uint32_t operation, PulseFileOperationRequestId *request_id);
    /* Synchronous owner-thread snapshot. Requires operations.own. */
    PulseStatus(PULSE_CALL *get)(void *, PulseFileOperationRequestId request_id, PulseFileOperation *out);
    /* Cancels preparation/confirmation or the accepted controlled task. */
    PulseStatus(PULSE_CALL *cancel)(void *, PulseFileOperationRequestId request_id);
} PulseFileOpsV1;
/* V2 preserves V1 unchanged. Query version 2 with sizeof(PulseFileOpsV2).
   submit retains the V1 actions; use submit_to_directory for the two new actions.
   Requires files.transferToDirectory, files.readDirectory and operations.own.
   destination must be a successfully opened pulse.directories handle belonging
   to this attachment. No source/destination paths or confirmation are accepted.
   Closing the handle before task submission cancels preparation/confirmation;
   after task submission, use cancel(request_id) to cancel execution.
   Directory handles resolve paths at worker preparation; object identity is
   checked by the controlled engine after preparation. Existing destinations
   fail without replacement. The request is not an atomic multi-file transaction;
   external changes during execution can still produce partial results.
   File-only limits and engine exclusions still apply. */
typedef struct PulseFileOpsV2 {
    uint32_t size;
    uint32_t version;
    void *context;
    PulseStatus(PULSE_CALL *submit)(void *, uint32_t operation, PulseFileOperationRequestId *request_id);
    PulseStatus(PULSE_CALL *get)(void *, PulseFileOperationRequestId request_id, PulseFileOperation *out);
